pages.css:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif;
}

body {
    background: linear-gradient(135deg, #f5f7fa 0%, #e4edf5 100%);
    color: #333;
    line-height: 1.6;
    padding: 20px;
    min-height: 100vh;
    border-top: 15px solid #4ECDC4;
}

.container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 25px;
}

header {
    text-align: center;
    margin-bottom: 40px;
    padding: 25px;
    background: linear-gradient(90deg, #FF9A9E 0%, #FAD0C4 100%);
    border-radius: 20px;
    box-shadow: 0 10px 25px rgba(255, 154, 158, 0.3);
    color: #fff;
    position: relative;
    overflow: hidden;
}

header::before {
    content: "";
    position: absolute;
    top: -10px;
    left: -10px;
    right: -10px;
    bottom: -10px;
    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M0,0 L100,0 L100,100 Z" fill="rgba(255,255,255,0.1)"/></svg>');
    background-size: cover;
    z-index: 0;
}

h1 {
    font-size: 2.8rem;
    margin-bottom: 15px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.2);
    position: relative;
    z-index: 1;
}

.subtitle {
    font-size: 1.3rem;
    opacity: 0.95;
    max-width: 800px;
    margin: 0 auto;
    position: relative;
    z-index: 1;
}

.course-stats {
    display: flex;
    justify-content: center;
    gap: 30px;
    margin-top: 25px;
    flex-wrap: wrap;
    position: relative;
    z-index: 1;
}

.stat {
    background: rgba(255, 255, 255, 0.9);
    padding: 12px 25px;
    border-radius: 50px;
    color: #FF6B8B;
    font-weight: bold;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    display: flex;
    align-items: center;
    gap: 10px;
}

.directory-container {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(450px, 1fr));
    gap: 25px;
    margin-bottom: 50px;
}

.chapter-card {
    background: white;
    border-radius: 18px;
    padding: 25px;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
    transition: all 0.3s ease;
    border-left: 8px solid #A6E3E9;
    display: flex;
    align-items: flex-start;
    position: relative;
    overflow: hidden;
}

.chapter-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.15);
    border-left-color: #FFD166;
}

.chapter-card::after {
    content: "";
    position: absolute;
    top: 0;
    right: 0;
    width: 80px;
    height: 80px;
    background: #FFD166;
    border-radius: 0 0 0 80px;
    opacity: 0.1;
}

.chapter-number {
    flex-shrink: 0;
    width: 60px;
    height: 60px;
    background: linear-gradient(135deg, #FF9A9E 0%, #FAD0C4 100%);
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.8rem;
    font-weight: bold;
    margin-right: 22px;
    box-shadow: 0 5px 15px rgba(255, 154, 158, 0.4);
}

.chapter-content {
    flex: 1;
}

.chapter-title {
    font-size: 1.4rem;
    color: #2A6171;
    margin-bottom: 12px;
    font-weight: 700;
}

.chapter-desc {
    color: #555;
    font-size: 1rem;
    margin-bottom: 18px;
}

.chapter-link {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: #4ECDC4;
    color: white;
    padding: 10px 20px;
    border-radius: 50px;
    text-decoration: none;
    font-weight: 600;
    font-size: 0.95rem;
    transition: all 0.3s;
    box-shadow: 0 4px 10px rgba(78, 205, 196, 0.3);
}

.chapter-link:hover {
    background: #3DBBB2;
    transform: scale(1.05);
    box-shadow: 0 6px 15px rgba(78, 205, 196, 0.5);
}

footer {
    text-align: center;
    padding: 30px;
    margin-top: 40px;
    background: linear-gradient(90deg, #A6E3E9 0%, #CBF1F5 100%);
    border-radius: 20px;
    color: #2A6171;
    font-size: 1.2rem;
    font-weight: bold;
    box-shadow: 0 8px 20px rgba(166, 227, 233, 0.4);
    border-top: 5px solid #FFD166;
}

.footer-highlight {
    color: #FF6B8B;
    font-size: 1.3rem;
    margin-top: 5px;
    display: block;
}

@media (max-width: 1100px) {
    .directory-container {
        grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));
    }
}

@media (max-width: 768px) {
    .directory-container {
        grid-template-columns: 1fr;
    }

    h1 {
        font-size: 2.2rem;
    }

    .chapter-card {
        flex-direction: column;
        align-items: flex-start;
    }

    .chapter-number {
        margin-bottom: 20px;
    }

    .course-stats {
        flex-direction: column;
        align-items: center;
        gap: 15px;
    }
}

:root {
    --primary-color: #4CAF50; /* 青草绿 */
    --secondary-color: #FF9800; /* 活力橙 */
    --accent-color: #2196F3; /* 天空蓝 */
    --light-bg: #F9FBE7; /* 米黄/浅鹅黄 */
    --card-bg: #FFFFFF;
    --text-dark: #333333;
    --text-light: #666666;
    --border-color: #C8E6C9; /* 浅绿边框 */
    --shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
}
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif;
}
body {
    background-color: var(--light-bg);
    color: var(--text-dark);
    line-height: 1.6;
    padding: 20px;
    background-image: 
        radial-gradient(circle at 10% 20%, rgba(255, 255, 255, 0.8) 0%, transparent 20%),
        radial-gradient(circle at 90% 80%, rgba(255, 255, 255, 0.6) 0%, transparent 20%);
}
.double-border-container {
    border: 8px solid var(--primary-color);
    border-radius: 20px;
    padding: 5px;
    background-color: white;
    box-shadow: var(--shadow);
    position: relative;
    max-width: 1200px;
    margin: 0 auto;
}
.double-border-container::before {
    content: '';
    position: absolute;
    top: -12px;
    left: -12px;
    right: -12px;
    bottom: -12px;
    border: 4px solid var(--secondary-color);
    border-radius: 28px;
    pointer-events: none;
    z-index: -1;
}
.container {
    padding: 30px;
    border-radius: 15px;
    background-color: var(--card-bg);
}
header {
    text-align: center;
    margin-bottom: 40px;
    padding-bottom: 20px;
    border-bottom: 3px dashed var(--border-color);
}
h1 {
    color: var(--primary-color);
    font-size: 2.8em;
    margin-bottom: 10px;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.1);
}
.subtitle {
    color: var(--secondary-color);
    font-size: 1.4em;
    font-weight: 300;
}
h2 {
    color: var(--accent-color);
    border-left: 6px solid var(--secondary-color);
    padding-left: 15px;
    margin: 30px 0 20px;
    font-size: 1.8em;
}
h3 {
    color: var(--primary-color);
    margin: 20px 0 10px;
    font-size: 1.4em;
}
p {
    margin-bottom: 15px;
    text-align: justify;
}
.highlight {
    background-color: #E8F5E9;
    padding: 15px;
    border-radius: 10px;
    border-left: 5px solid var(--primary-color);
    margin: 20px 0;
}
.card {
    background: white;
    border-radius: 12px;
    padding: 20px;
    margin: 20px 0;
    box-shadow: 0 4px 8px rgba(0,0,0,0.05);
    border: 2px solid var(--border-color);
    transition: transform 0.3s ease;
}
.card:hover {
    transform: translateY(-5px);
}
table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    border-radius: 10px;
    overflow: hidden;
    box-shadow: 0 4px 6px rgba(0,0,0,0.05);
}
th {
    background-color: var(--primary-color);
    color: white;
    padding: 15px;
    text-align: left;
}
td {
    padding: 12px 15px;
    border-bottom: 1px solid var(--border-color);
}
tr:nth-child(even) {
    background-color: #F9F9F9;
}
ul, ol {
    padding-left: 25px;
    margin: 15px 0;
}
li {
    margin-bottom: 8px;
}
.svg-container {
    display: flex;
    justify-content: center;
    margin: 30px 0;
    background: #f5fdf6;
    padding: 20px;
    border-radius: 12px;
}
.tool-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 20px;
    margin: 25px 0;
}
.tool-item {
    background: linear-gradient(135deg, #E3F2FD, #F1F8E9);
    padding: 20px;
    border-radius: 12px;
    border-top: 5px solid var(--accent-color);
}
.tool-item h4 {
    color: var(--accent-color);
    margin-bottom: 10px;
}
footer {
    text-align: center;
    margin-top: 50px;
    padding-top: 20px;
    border-top: 2px solid var(--border-color);
    color: var(--text-light);
    font-size: 1.1em;
    font-weight: bold;
    letter-spacing: 1px;
}
.code-block {
    background-color: #2d2d2d;
    color: #f8f8f2;
    padding: 20px;
    border-radius: 10px;
    overflow-x: auto;
    margin: 20px 0;
    font-family: 'Consolas', 'Monaco', monospace;
    border-left: 5px solid var(--secondary-color);
}
.keyword { color: #ff79c6; }
.comment { color: #6272a4; }
.function { color: #50fa7b; }
.string { color: #f1fa8c; }
