    padding: 20px;
    background-color: var(--background-color);
    color: var(--text-color);
    line-height: 1.6;
}
.container {
    max-width: 1200px;
    margin: 0 auto;
    background: white;
    border: double 10px var(--border-color);
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
    overflow: hidden;
    padding: 30px;
}
header {
    text-align: center;
    padding: 30px 20px;
    background: linear-gradient(135deg, var(--primary-color), var(--accent-color));
    color: white;
    border-bottom: double 8px var(--light-color);
    margin: -30px -30px 30px -30px;
}
h1 {
    font-size: 2.8em;
    margin-bottom: 10px;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.2);
}
h2 {
    color: var(--secondary-color);
    border-left: 6px solid var(--accent-color);
    padding-left: 15px;
    margin-top: 40px;
}
h3 {
    color: var(--primary-color);
}
.section {
    margin-bottom: 40px;
    padding: 20px;
    border-radius: 10px;
    background-color: #f9f9f9;
    border: 2px dashed var(--accent-color);
}
table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    border: 2px solid var(--border-color);
}
th, td {
    border: 1px solid var(--border-color);
    padding: 12px;
    text-align: left;
}
th {
    background-color: var(--light-color);
    color: var(--text-color);
}
ul, ol {
    padding-left: 25px;
}
li {
    margin-bottom: 8px;
}
.code-block {
    background-color: #2d2d2d;
    color: #f8f8f2;
    padding: 15px;
    border-radius: 8px;
    overflow-x: auto;
    font-family: 'Consolas', monospace;
    border-left: 5px solid var(--secondary-color);
    margin: 20px 0;
}
.svg-container {
    text-align: center;
    margin: 30px 0;
    padding: 20px;
    background: white;
    border-radius: 10px;
    border: 2px solid var(--primary-color);
}
footer {
    text-align: center;
    margin-top: 50px;
    padding: 25px;
    background: linear-gradient(135deg, var(--border-color), #5D4037);
    color: white;
    font-size: 1.2em;
    border-top: double 8px var(--light-color);
    margin: 30px -30px -30px -30px;
}
.highlight {
    background-color: var(--light-color);
    padding: 3px 6px;
    border-radius: 4px;
    font-weight: bold;
}
.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    margin: 30px 0;
}
.card {
    background: white;
    padding: 20px;
    border-radius: 10px;
    border-top: 6px solid var(--accent-color);
    box-shadow: 0 5px 15px rgba(0,0,0,0.05);
}
